    private void jButtonConectarActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jButtonConectarActionPerformed
        servidor = jTextFieldEnderecoServidor.getText();

        if (servidor.isEmpty()) {
            JOptionPane.showMessageDialog(this, "Informe o IP do servidor!");
            jTextFieldEnderecoServidor.requestFocus();
            return;
        }
        try {
            consulta = (IConsultaSessao) Naming.lookup("rmi://" + servidor + "/ConsultaSessao");
            jTextAreaResultadoPesquisa.setText("Realizando conexão com o servidor...sucesso\n");
            jButtonPesquisar.setEnabled(true);
            jButtonConectar.setEnabled(false);
            jTextFieldNumeroCelularPesquisa.requestFocus();
        } catch (Exception e) {
        JOptionPane.showMessageDialog(this, "Um erro aconteceu na conexão com o servidor");
    }
    }//GEN-LAST:event_jButtonConectarActionPerformed

    private void jButtonPesquisarActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jButtonPesquisarActionPerformed
        numeroCelular = jTextFieldNumeroCelularPesquisa.getText().trim();

        if (numeroCelular.equals("")) {
            JOptionPane.showMessageDialog(this,"Número de celular não informado");
            jTextFieldNumeroCelularPesquisa.requestFocus();
            return;
        }
        try {
            dadosSessao = consulta.consultarSessao(numeroCelular);
        } catch (RemoteException e) {
            JOptionPane.showMessageDialog(this, "Um erro aconteceu na conexão com o servidor");
            return;
        }

        if (dadosSessao == null) {
            JOptionPane.showMessageDialog(this,"Número de celular não encontrado");
            jTextFieldNumeroCelularPesquisa.setText("");
            jTextFieldNumeroCelularPesquisa.requestFocus();
            return;
        }

        // Mostra um dado da sessão por linha
        dadosSessao = dadosSessao.replace("{", "").replace("}", "").replace(", ", "\n");
        jTextAreaResultadoPesquisa.setText("Celular: " + numeroCelular + "\n\n" + dadosSessao);
        jTextAreaResultadoPesquisa.setCaretPosition(0);
    }//GEN-LAST:event_jButtonPesquisarActionPerformed

